             Trace.call1("DisplayControlImpl.init doMakeWindow");
             //Now create the gui
             doMakeWindow();
             Trace.call2("DisplayControlImpl.init doMakeWindow");
         }
 
 
         addToControlContext();
 
 
 
         //Get the color table, range, etc.
         instantiateAttributes();
 
 
 
         haveInitialized = true;
 
         if ( !isVisible) {
             setDisplayVisibility(false);
         }
 
 
 
